export function Modal({ open, onClose, children }: { open: boolean; onClose: () => void; children: React.ReactNode }) {
  if (!open) return null
  return (
    <div className="overlay">
      <div className="modal">
        <span className="close" onClick={onClose}><svg width="16" height="16"><path d="M0 0L16 16M16 0L0 16" /></svg></span>
        {children}
      </div>
    </div>
  )
}
